import{af as a,z as t,J as o,ab as i}from"./chunks/framework.BnTFvF69.js";const u=JSON.parse('{"title":"RTK","description":"","frontmatter":{"outline":"shallow","order":6,"title":"RTK"},"headers":[],"relativePath":"apps/admin/devices/rtk.md","filePath":"apps/admin/devices/rtk.md"}'),r={name:"apps/admin/devices/rtk.md"};function n(s,e,d,l,c,p){return t(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793279959000"},[...e[0]||(e[0]=[i('<h1 id="manage-rtk" tabindex="-1">Manage RTK <a class="header-anchor" href="#manage-rtk" aria-label="Permalink to &quot;Manage RTK&quot;">​</a></h1><p>RTK-specific controls are available for RTK-capable devices.</p><p>Open the RTK dialog from the device row actions to view and modify RTK settings by clicking the <i class="eva eva-star-outline" style="color:#fc7c3d;font-size:1.5em;"></i>.</p><p>The settings can be used to configure both rover and base station modes.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="group" tabindex="-1">Group <a class="header-anchor" href="#group" aria-label="Permalink to &quot;Group&quot;">​</a></h3><p>Selected by the user. Any number 0 - 250.</p><p>All devices assigned the same group number will only connect to a Base unit with the same group number. This prevents cross communication between groups. This is useful when you have more than one group working close to each other.</p><p>Each group will be connected to their own Base unit. Ensure each group is labelled with the corresponding number.</p><h3 id="ntrip-settings" tabindex="-1">NTRIP Settings <a class="header-anchor" href="#ntrip-settings" aria-label="Permalink to &quot;NTRIP Settings&quot;">​</a></h3><p>Input these configuration settings as per the supplier and setup.</p><p>This is compulsory for a high level of accuracy.</p><h2 id="base-mode" tabindex="-1">Base mode <a class="header-anchor" href="#base-mode" aria-label="Permalink to &quot;Base mode&quot;">​</a></h2><h3 id="fixed-position" tabindex="-1">Fixed Position <a class="header-anchor" href="#fixed-position" aria-label="Permalink to &quot;Fixed Position&quot;">​</a></h3><p>If you have known GPS coordinates select Fixed Position to green and input Altitude, and, Latitude &amp; Longitude coordinates.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/URMQxLP.png" alt="" tabindex="0"><figcaption></figcaption></figure><h3 id="survey" tabindex="-1">Survey <a class="header-anchor" href="#survey" aria-label="Permalink to &quot;Survey&quot;">​</a></h3><p>Survey mode allows the base station to determine its own position.</p><h2 id="rover" tabindex="-1">Rover <a class="header-anchor" href="#rover" aria-label="Permalink to &quot;Rover&quot;">​</a></h2><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/QP5Im8F.png" alt="" tabindex="0"><figcaption></figcaption></figure>',20)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
